defmodule SellApp.OperationContractTest do
  use ExUnit.Case, async: true
  alias SellApp.Client

  test "account API keys omit the default store" do
    client =
      Client.new(
        api_key: "account-key",
        store: "configured-store",
        req_options: [plug: {Req.Test, __MODULE__}]
      )

    Req.Test.stub(__MODULE__, fn conn ->
      assert Plug.Conn.get_req_header(conn, "authorization") == ["Bearer account-key"]
      expected = if conn.request_path == "/api/v2/products", do: ["configured-store"], else: []
      assert Plug.Conn.get_req_header(conn, "x-store") == expected
      Req.Test.json(conn, %{})
    end)

    for path <- ["/v2/me", "/v2/stores", "/v2/stores/12", "/v2/products"] do
      assert {:ok, _} = Client.request(client, :get, path)
    end
  end

  test "credentials stay within their operation contract" do
    client =
      Client.new(
        api_key: "seller",
        store: "shop",
        access_token: "oauth",
        customer_session: "portal",
        req_options: [plug: {Req.Test, __MODULE__}]
      )

    Req.Test.stub(__MODULE__, fn conn ->
      expected =
        case conn.request_path do
          "/api/v2/invoices" -> {"Bearer oauth", "shop"}
          "/api/v2/customer-portal/me" -> {"Bearer portal", nil}
          "/.well-known/oauth-authorization-server" -> {nil, nil}
        end

      {bearer, store} = expected
      assert Plug.Conn.get_req_header(conn, "authorization") == if(bearer, do: [bearer], else: [])
      assert Plug.Conn.get_req_header(conn, "x-store") == if(store, do: [store], else: [])
      Req.Test.json(conn, %{})
    end)

    assert {:ok, _} = Client.request(client, :get, "/v2/invoices")
    assert {:ok, _} = Client.request(client, :get, "/v2/customer-portal/me")
    assert {:ok, _} = Client.request(client, :get, "/.well-known/oauth-authorization-server")

    assert {:error, %SellApp.Error.Configuration{}} =
             Client.request(Client.new(api_key: "seller"), :get, "/v2/customer-portal/me")

    assert {:error, %SellApp.Error.Configuration{}} =
             Client.request(Client.new(access_token: "oauth"), :get, "/v2/invoices")
  end

  test "protocol forms and redirects never expose seller credentials" do
    client =
      Client.new(
        api_key: "seller",
        store: "shop",
        max_retries: 3,
        req_options: [plug: {Req.Test, __MODULE__}]
      )

    Req.Test.stub(__MODULE__, fn conn ->
      assert conn.request_path == "/oauth/token"
      assert Plug.Conn.get_req_header(conn, "authorization") == []
      assert Plug.Conn.get_req_header(conn, "x-store") == []
      {:ok, body, conn} = Plug.Conn.read_body(conn)
      assert URI.decode_query(body)["refresh_token"] == "secret + value"
      send(self(), :attempt)

      conn
      |> Plug.Conn.put_resp_header("location", "https://storage.invalid/file")
      |> Plug.Conn.send_resp(302, "")
    end)

    assert {:ok, response} =
             Client.request(
               client,
               :post,
               "/oauth/token",
               %{"grant_type" => "refresh_token", "refresh_token" => "secret + value"},
               with_response: true
             )

    assert response.status == 302
    assert_receive :attempt
    refute_receive :attempt
  end

  test "authorization method preserves HTML and response metadata" do
    html = "<!doctype html><title>Consent &amp; café</title>"
    client = Client.new(req_options: [plug: {Req.Test, __MODULE__}])

    Req.Test.stub(__MODULE__, fn conn ->
      assert conn.request_path == "/oauth/authorize"

      conn
      |> Plug.Conn.put_resp_content_type("text/html")
      |> Plug.Conn.put_resp_header("x-request-id", "consent-request")
      |> Plug.Conn.send_resp(200, html)
    end)

    assert {:ok, ^html} = SellApp.OAuth.get_oauth_authorization_request(client)

    assert {:ok, response} =
             SellApp.OAuth.get_oauth_authorization_request(client, %{}, with_response: true)

    assert response.data == html
    assert response.status == 200
    assert response.headers["x-request-id"] == ["consent-request"]
  end

  test "one-time customer session creation cannot be made replayable by a header" do
    Req.Test.stub(__MODULE__, fn conn ->
      send(self(), :attempt)
      Plug.Conn.send_resp(conn, 503, "unavailable")
    end)

    client = Client.new(api_key: "seller", req_options: [plug: {Req.Test, __MODULE__}])

    assert {:error, _} =
             Client.request(client, :post, "/v2/customer-sessions", %{},
               idempotency_supported: true,
               idempotency_key: "same"
             )

    assert_receive :attempt
    refute_receive :attempt
  end

  test "cursor pages preserve empty-page continuation" do
    page =
      SellApp.Page.from_map(
        %{"data" => [], "meta" => %{"next_cursor" => "next"}},
        "data",
        & &1,
        fn cursor ->
          assert cursor == "next"

          {:ok,
           SellApp.Page.from_map(
             %{"data" => [1], "meta" => %{"next_cursor" => nil}},
             "data",
             & &1,
             nil,
             pagination_param: "cursor"
           )}
        end,
        pagination_param: "cursor"
      )

    assert Enum.to_list(SellApp.Page.stream(page)) == [1]
  end
end
